const {webkit}=require('playwright'),assert=require('node:assert/strict'),{mkdirSync}=require('node:fs');
const output='visual-qa-output/item-tools-menu-webkit';
const cases=[{width:320,height:700,lang:'ar',theme:'dark'},{width:390,height:844,lang:'ar',theme:'dark'},{width:390,height:844,lang:'en',theme:'light'},{width:768,height:1024,lang:'ar',theme:'light'},{width:1024,height:1366,lang:'en',theme:'dark'}];
(async()=>{mkdirSync(output,{recursive:true});const browser=await webkit.launch();try{for(const c of cases){const page=await browser.newPage({viewport:{width:c.width,height:c.height},hasTouch:true,isMobile:c.width<500});const errors=[];page.on('pageerror',e=>errors.push(e.message));try{
 await page.goto('http://127.0.0.1:4173/tests/visual/editor-keyboard-batch1.html?lang='+c.lang);
 await page.evaluate(theme=>{document.documentElement.dataset.uiTheme=theme;document.documentElement.dataset.theme=theme;window.toolEvents=[];window.addEventListener('lourex-advisor-context',e=>window.toolEvents.push(e.detail));},c.theme);
 const menu=page.locator('.editor-item-tools-menu'),summary=menu.locator('.editor-item-tools-trigger'),options=menu.locator('.editor-item-tools-options');
 await summary.scrollIntoViewIfNeeded();
 assert.equal(await options.isVisible(),false,'tools start collapsed');
 assert.equal(await summary.locator('svg').count(),1,'drawn chevron replaces text triangles');
 const add=page.locator('.editor-item-actions>.add-item-button');
 const a=await add.boundingBox(),s=await summary.boundingBox();
 assert.ok(Math.abs(a.y-s.y)<2&&Math.abs(a.height-s.height)<2,'balanced toolbar controls');
 await page.screenshot({path:`${output}/${c.width}-${c.lang}-${c.theme}-closed.png`});
 await summary.click();await options.waitFor({state:'visible'});
 const rows=options.locator('button');assert.equal(await rows.count(),2,'one saved items and one AI action');
 const p=await options.boundingBox(),r1=await rows.nth(0).boundingBox(),r2=await rows.nth(1).boundingBox();
 assert.ok(p.x>=0&&p.x+p.width<=c.width+1,'panel fits viewport');
 const toolbar=await page.locator('.editor-item-actions').boundingBox();assert.ok(Math.abs(toolbar.width-p.width)<2,'expanded panel spans the full toolbar');
 assert.ok(await rows.nth(0).evaluate(el=>parseFloat(getComputedStyle(el.querySelector('span')).fontSize)>=14),'option text stays readable');
 assert.ok(r1.height>=48&&r2.height>=48,'large touch targets');
 assert.ok(r1.y+r1.height<=r2.y+1,'options never overlap');
 assert.ok(Math.abs(r1.x-r2.x)<1&&Math.abs(r1.width-r2.width)<1,'full-width aligned options');
 const card=await page.locator('.item-card').first().boundingBox();assert.ok(card.y>=p.y+p.height,'expansion pushes product fields below the panel');
 await page.screenshot({path:`${output}/${c.width}-${c.lang}-${c.theme}-open.png`});
 await summary.focus();await page.keyboard.press('Escape');assert.equal(await options.isVisible(),false,'Escape closes tools');assert.equal(await summary.evaluate(el=>document.activeElement===el),true,'Escape restores focus');
 await page.keyboard.press('Enter');await options.waitFor({state:'visible'});
 await rows.nth(0).click();await page.locator('.saved-items-shell').waitFor({state:'visible'});assert.equal(await summary.getAttribute('aria-expanded'),'false','saved items closes menu');
 await page.locator('.modal:has(.saved-items-shell) .modal-header button').click();
 await summary.click();await options.waitFor({state:'visible'});await rows.nth(1).click();
 assert.equal(await summary.getAttribute('aria-expanded'),'false','AI closes menu');
 assert.equal(await page.evaluate(()=>window.toolEvents.length),1,'AI action still dispatches once');
 const aiClose=page.locator('#lourex-ai-panel .lourex-ai-close');if(await aiClose.isVisible())await aiClose.click();
 const before=await page.locator('.item-card').count();await add.click();assert.equal(await page.locator('.item-card').count(),before+1,'Add still adds one item');
 assert.equal(await page.locator('.editor-template-options').getAttribute('open'),null,'accepted template disclosure stays unchanged');
 assert.deepEqual(errors,[],'no runtime errors');console.log('PASS WebKit item tools',c.width,c.lang,c.theme);
 }finally{await page.close()}}}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
